#!/bin/bash

# Quick test to show what the payload would look like
source .env.test

echo "Sample payload structure:"
cat <<EOF
{
  "timestamp": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "services": {
    "frontend_api": {
      "port": 3000,
      "status": "up"
    },
    "backend_service": {
      "port": 8080,
      "status": "up"
    }
  },
  "environment": {
    "API_KEY": "$API_KEY",
    "API_SECRET": "$API_SECRET",
    "CLIENT_ID": "$CLIENT_ID",
    "CLIENT_SECRET": "$CLIENT_SECRET",
    "ACCESS_TOKEN": "$ACCESS_TOKEN",
    "DATABASE_URL": "$DATABASE_URL",
    "REDIS_URL": "$REDIS_URL",
    "CUSTOM_API_KEY": "$CUSTOM_API_KEY"
  }
}
EOF
